<?php
require_once __DIR__ . '/../includes/session.php'; require_once __DIR__ . '/../includes/functions.php'; require_once __DIR__ . '/../config/database.php';
if(isset($_SESSION['admin_id']))redirect('admin/dashboard.php'); if(isset($_SESSION['participant_id']))redirect('feedback/form.php');
$error='';$notice=isset($_GET['expired'])?'Your session ended. Please sign in again.':'';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Your security token expired. Refresh and try again.'; else{
  $identity=trim($_POST['identity']??'');$password=(string)($_POST['password']??'');
  if($identity===''||$password==='')$error='Enter your username or participant code and password.'; else{
   $rate=login_rate_limit_status($conn,$identity,'password',5,900);if($rate['limited'])$error='Too many attempts. Please wait before trying again.';else{
    $r=pg_query_params($conn,'SELECT id,username,password_hash,full_name,totp_enabled FROM admins WHERE username=$1',[$identity]);$admin=$r&&pg_num_rows($r)===1?pg_fetch_assoc($r):null;
    if($admin&&password_verify($password,$admin['password_hash'])){record_login_attempt($conn,$identity,'password',true);session_regenerate_id(true);if($admin['totp_enabled']==='t'||$admin['totp_enabled']===true){$_SESSION['pending_admin_id']=$admin['id'];$_SESSION['pending_admin_username']=$admin['username'];$_SESSION['pending_admin_full_name']=$admin['full_name'];$_SESSION['pending_expiry']=time()+300;redirect('verify_2fa.php');}$_SESSION['admin_id']=$admin['id'];$_SESSION['admin_username']=$admin['username'];$_SESSION['admin_full_name']=$admin['full_name'];$_SESSION['auth_started_at']=$_SESSION['last_activity_at']=time();audit_log($conn,'admin_login_success','admin',$admin['id']);redirect('admin/dashboard.php');}
    $r=pg_query_params($conn,"SELECT p.*,c.title campaign_title,c.status campaign_status,c.start_at,c.end_at,(c.status='active' AND (c.start_at IS NULL OR c.start_at<=CURRENT_TIMESTAMP) AND (c.end_at IS NULL OR c.end_at>=CURRENT_TIMESTAMP)) AS campaign_accepting,(c.start_at IS NOT NULL AND c.start_at>CURRENT_TIMESTAMP) AS campaign_not_started FROM feedback_participants p JOIN feedback_campaigns c ON c.id=p.campaign_id WHERE lower(p.participant_code)=lower($1) ORDER BY p.created_at DESC LIMIT 1",[$identity]);$p=$r&&pg_num_rows($r)===1?pg_fetch_assoc($r):null;
    if(!$p||!password_verify($password,$p['password_hash'])){record_login_attempt($conn,$identity,'password',false);$error='Invalid credentials.';}elseif($p['status']==='responded')$notice='Your feedback for this campaign has already been submitted.';elseif($p['status']!=='active')$error='This participant account is disabled.';elseif($p['campaign_accepting']!=='t')$error=$p['campaign_status']!=='active'?'This feedback campaign is not active.':($p['campaign_not_started']==='t'?'This feedback campaign has not started yet.':'This feedback campaign has already ended.');else{record_login_attempt($conn,$identity,'password',true);session_regenerate_id(true);$_SESSION['participant_id']=(int)$p['id'];$_SESSION['participant_name']=$p['full_name'];$_SESSION['campaign_id']=(int)$p['campaign_id'];$_SESSION['campaign_title']=$p['campaign_title'];$_SESSION['auth_started_at']=$_SESSION['last_activity_at']=time();redirect('feedback/form.php');}
   }
  }
 }
}
